   121→        public static void RegisterDecoders(Assembly assembly, bool canOverrideExistingDecoders = false)
   122→        {
   123→            foreach (Type? type in assembly.GetExportedTypes())
   124→            {
   125→                if (!type.IsClass || type.IsAbstract || type.IsGenericTypeDefinition)
   126→                {
   127→                    continue;
   128→                }
   129→
   130→                if (type.GetCustomAttribute<SkipGlobalRegistration>() is not null)
   131→                {
   132→                    continue;
   133→                }
   134→
   135→                Type[]? implementedInterfaces = type.GetInterfaces();
   136→                foreach (Type? implementedInterface in implementedInterfaces)
   137→                {
   138→                    if (!implementedInterface.IsGenericType)
   139→                    {
   140→                        continue;
   141→                    }
   142→
   143→                    Type? interfaceGenericDefinition = implementedInterface.GetGenericTypeDefinition();
   144→                    if (interfaceGenericDefinition == typeof(IRlpDecoder<>).GetGenericTypeDefinition())
   145→                    {
   146→                        bool isSetForAnyAttribute = false;
   147→                        IRlpDecoder? instance = null;
   148→
   149→                        foreach (DecoderAttribute rlpDecoderAttr in type.GetCustomAttributes<DecoderAttribute>())
   150→                        {
   151→                            RlpDecoderKey key = new(implementedInterface.GenericTypeArguments[0], rlpDecoderAttr.Key);
   152→                            AddEncoder(key);
   153→
   154→                            isSetForAnyAttribute = true;
   155→                        }
   156→
   157→                        if (!isSetForAnyAttribute)
   158→                        {
   159→                            AddEncoder(new(implementedInterface.GenericTypeArguments[0]));
   160→                        }
   161→
   162→                        void AddEncoder(RlpDecoderKey key)
   163→                        {
   164→                            using Lock.Scope _ = _decoderLock.EnterScope();
   165→                            if (!_decoderBuilder.TryGetValue(key, out IRlpDecoder? value) || canOverrideExistingDecoders)
   166→                            {
   167→                                try
   168→                                {
   169→                                    _decoderBuilder[key] = instance ??= (IRlpDecoder)(type.GetConstructor(Type.EmptyTypes) is not null ?
   170→                                        Activator.CreateInstance(type) :
   171→                                        Activator.CreateInstance(type, BindingFlags.CreateInstance | BindingFlags.OptionalParamBinding, null, [Type.Missing], null));
   172→                                }
   173→                                catch (Exception)
   174→                                {
   175→                                    throw new ArgumentException($"Unable to set decoder for {key}, because {type} decoder has no suitable constructor.");
   176→                                }
   177→                            }
   178→                            else
   179→                            {
   180→                                throw new InvalidOperationException($"Unable to override decoder for {key}, because the following decoder is already set: {value}.");
   181→                            }
   182→                        }
   183→                    }
   184→                }
   185→            }
   186→
   187→            // Mark FrozenDictionary as null to force re-creation
   188→            _decoders = null;
   189→        }
