   243→        internal static byte[] ByteSpanToArray(ReadOnlySpan<byte> span)
   244→        {
   245→            if (span.Length == 0)
   246→            {
   247→                return [];
   248→            }
   249→
   250→            if (span.Length == 1)
   251→            {
   252→                int value = span[0];
   253→                var arrays = RlpStream.SingleByteArrays;
   254→                if ((uint)value < (uint)arrays.Length)
   255→                {
   256→                    return arrays[value];
   257→                }
   258→            }
   259→
   260→            return span.ToArray();
   261→        }
