   327→
   328→            IRlpStreamDecoder<T>? rlpStreamDecoder = GetStreamDecoder<T>();
   329→            if (rlpStreamDecoder is not null)
   330→            {
   331→                int totalLength = rlpStreamDecoder.GetLength(item, behaviors);
   332→                RlpStream stream = new(totalLength);
   333→                rlpStreamDecoder.Encode(stream, item, behaviors);
