   425→        public static int Encode(Span<byte> buffer, int position, ReadOnlySpan<byte> input)
   426→        {
   427→            if (input.Length == 1 && input[0] < 128)
   428→            {
   429→                buffer[position++] = input[0];
   430→                return position;
   431→            }
   432→
   433→            if (input.Length < 56)
   434→            {
   435→                byte smallPrefix = (byte)(input.Length + 128);
   436→                buffer[position++] = smallPrefix;
   437→            }
   438→            else
   439→            {
   440→                int lengthOfLength = LengthOfLength(input.Length);
   441→                byte prefix = (byte)(183 + lengthOfLength);
   442→                buffer[position++] = prefix;
   443→                position += SerializeLength(input.Length, buffer[position..]);
   444→            }
   445→
   446→            input.CopyTo(buffer.Slice(position, input.Length));
   447→            position += input.Length;
   448→
   449→            return position;
   450→        }
