   456→            if ((uint)newPosition > (uint)buffer.Length)
   457→            {
   458→                ThrowArgumentOutOfRangeException();
   459→            }
   460→
   461→            Unsafe.Add(ref MemoryMarshal.GetReference(buffer), (nuint)position) = 160;
   462→            Unsafe.As<byte, ValueHash256>(ref Unsafe.Add(ref MemoryMarshal.GetReference(buffer), (nuint)position + 1)) = hash.ValueHash256;
   463→            return newPosition;
