   472→        [SkipLocalsInit]
   473→        public static Rlp Encode(ReadOnlySpan<byte> input)
   474→        {
   475→            // Handle special cases first
   476→            int length = input.Length;
   477→            if (length == 0)
   478→            {
   479→                return OfEmptyByteArray;
   480→            }
   481→
   482→            // If it's a single byte less than 128, it encodes to itself.
   483→            if (length == 1 && input[0] < 128)
   484→            {
   485→                return new Rlp(input[0]);
   486→            }
   487→
   488→            // For lengths < 56, the encoding is one byte of prefix + the data
   489→            if (length < 56)
   490→            {
   491→                // Allocate exactly what we need: 1 prefix byte + input length
   492→                byte[] rlpResult = GC.AllocateUninitializedArray<byte>(1 + length);
   493→                // First byte is 0x80 + length
   494→                rlpResult[0] = (byte)(0x80 + length);
   495→                // Copy input after the prefix
   496→                input.CopyTo(rlpResult.AsSpan(1));
   497→                return new Rlp(rlpResult);
   498→            }
   499→            else
   500→            {
   501→                int lengthOfLength = LengthOfLength(length);
   502→                // Total size = 1 prefix byte + lengthOfLength + data length
   503→                int totalSize = 1 + lengthOfLength + length;
   504→                byte[] rlpResult = GC.AllocateUninitializedArray<byte>(totalSize);
   505→                // Prefix: 0xb7 (183) + number of bytes in length
   506→                rlpResult[0] = (byte)(0xb7 + lengthOfLength);
   507→                SerializeLength(length, rlpResult.AsSpan(1, lengthOfLength));
   508→                // Finally copy the actual input
   509→                input.CopyTo(rlpResult.AsSpan(1 + lengthOfLength));
   510→                return new Rlp(rlpResult);
   511→            }
   512→        }
