   519→        private static int SerializeLength(int value, Span<byte> destination)
   520→        {
   521→            // We assume 0 <= value <= int.MaxValue
   522→            if (value < (1 << 8))
   523→            {
   524→                destination[0] = (byte)value;
   525→                return 1;
   526→            }
   527→
   528→            if (value < (1 << 16))
   529→            {
   530→                BinaryPrimitives.WriteUInt16BigEndian(destination, (ushort)value);
   531→                return 2;
   532→            }
   533→
   534→            if (value < (1 << 24))
   535→            {
   536→                destination[2] = (byte)value;
