   596→        [SkipLocalsInit]
   597→        public static Rlp Encode(params Rlp[] sequence)
   598→        {
   599→            int contentLength = 0;
   600→            for (int i = 0; i < sequence.Length; i++)
   601→            {
   602→                contentLength += sequence[i].Length;
   603→            }
   604→
   605→            int lengthOfLength = 0;
   606→            byte prefix;
   607→
   608→            if (contentLength < 56)
   609→            {
   610→                // Single-byte prefix: 0xc0 + length
   611→                prefix = (byte)(0xc0 + contentLength);
   612→            }
   613→            else
   614→            {
   615→                lengthOfLength = LengthOfLength(contentLength);
   616→                // Multi-byte prefix: 0xf7 + lengthOfLength
   617→                prefix = (byte)(0xf7 + lengthOfLength);
   618→            }
   619→
   620→            // Allocate the final buffer exactly once (prefix + optional length + content).
   621→            int totalSize = 1 + lengthOfLength + contentLength;
   622→            byte[] allBytes = GC.AllocateUninitializedArray<byte>(totalSize);
   623→
   624→            // Write prefix and length.
   625→            allBytes[0] = prefix;
   626→            int offset = 1;
   627→            if (lengthOfLength > 0)
   628→            {
   629→                SerializeLength(contentLength, allBytes.AsSpan(offset, lengthOfLength));
   630→                offset += lengthOfLength;
   631→            }
   632→
   633→            // Copy the content from all Rlp items.
   634→            for (int i = 0; i < sequence.Length; i++)
   635→            {
   636→                Buffer.BlockCopy(sequence[i].Bytes, 0, allBytes, offset, sequence[i].Length);
   637→                offset += sequence[i].Length;
   638→            }
   639→
   640→            // Wrap in Rlp and return.
   641→            return new Rlp(allBytes);
   642→        }
